// pointerCapability.js — the single source of truth for "should the custom
// cursor exist at all?". Shared by AgentsShowcase (which uses it to avoid even
// downloading the cursor chunk) and AgentCursor3D itself (which re-checks as a
// safety net). Keep it dependency-free and CSS-free so importing it is free.

// A real mouse, a device that can actually hover, a window wide enough that
// the cursor isn't in the way, and motion the visitor hasn't opted out of.
// `hover: hover` is what rules out phones and touch tablets — `pointer: fine`
// on its own passes on an iPad with a trackpad or a stylus.
export const CUSTOM_CURSOR_QUERY =
  "(pointer: fine) and (hover: hover) and (min-width: 900px) and (prefers-reduced-motion: no-preference)";

export const supportsCustomCursor = () =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia(CUSTOM_CURSOR_QUERY).matches;
